arguments.cmd:
mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <meta name="description" content="A global creative agency that challenges the status quo to create transformative experiences that win hearts and move markets in the eco-digital era." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #0A0A0A;
      --panel: #121212;
      --panel-2: #171717;
      --text: #FAFAFA;
      --muted: #B0B0B0;
      --line: #242424;
      --accent: #4DA3FF;
      --accent-2: #FFB347;
      --radius: 18px;
      --container: 1200px;
      --shadow: 0 12px 42px rgba(0, 0, 0, .35);
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
      background: radial-gradient(1200px 600px at 85% -10%, rgba(77,163,255,.12), transparent 55%),
                  radial-gradient(900px 500px at -10% 30%, rgba(255,179,71,.08), transparent 60%),
                  var(--bg);
      color: var(--text);
      line-height: 1.5;
    }

    a { color: inherit; text-decoration: none; }
    img { display: block; width: 100%; height: auto; border-radius: 12px; }

    .container { width: min(var(--container), calc(100% - 2rem)); margin-inline: auto; }
    .section { padding: 5.5rem 0; }
    .section h2 {
      font-size: clamp(1.8rem, 3vw, 2.8rem);
      line-height: 1.1;
      margin: 0 0 1.2rem;
      letter-spacing: -0.03em;
    }
    .eyebrow {
      font-size: .78rem;
      text-transform: uppercase;
      letter-spacing: .12em;
      color: var(--accent);
      margin-bottom: .8rem;
      font-weight: 600;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 50;
      backdrop-filter: blur(10px);
      background: rgba(10,10,10,.78);
      border-bottom: 1px solid var(--line);
    }

    .nav-wrap {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 76px;
      gap: 1rem;
    }

    .brand { font-weight: 800; letter-spacing: -.02em; font-size: 1.15rem; }
    .brand span { color: var(--accent); }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 1.2rem;
      color: #d8d8d8;
      font-size: .94rem;
    }

    .nav-links a { opacity: .9; transition: opacity .18s ease, color .18s ease; }
    .nav-links a:hover,
    .nav-links a:focus-visible { color: var(--text); opacity: 1; }

    .nav-right { display: flex; align-items: center; gap: .8rem; }

    .btn {
      border: 1px solid transparent;
      border-radius: 999px;
      padding: .62rem 1rem;
      font-weight: 600;
      font-size: .9rem;
      cursor: pointer;
      transition: transform .15s ease, background .2s ease, border-color .2s ease;
      min-height: 44px;
    }

    .btn:hover { transform: translateY(-1px); }
    .btn:active { transform: translateY(0); }

    .btn-primary { background: var(--accent); color: #081223; }
    .btn-primary:hover { background: #69b3ff; }
    .btn-ghost { background: transparent; color: var(--text); border-color: #2d2d2d; }
    .btn-ghost:hover { border-color: #4a4a4a; background: #171717; }

    .lang-toggle { position: relative; }
    .lang-menu {
      position: absolute;
      right: 0;
      top: calc(100% + .4rem);
      width: 180px;
      background: #121212;
      border: 1px solid #2a2a2a;
      border-radius: 12px;
      padding: .35rem;
      display: none;
      box-shadow: var(--shadow);
    }
    .lang-menu.show { display: block; }
    .lang-menu button {
      width: 100%;
      border: 0;
      background: transparent;
      color: #e9e9e9;
      text-align: left;
      padding: .62rem .7rem;
      border-radius: 8px;
      cursor: pointer;
    }
    .lang-menu button:hover,
    .lang-menu button:focus-visible { background: #202020; }

    .menu-toggle { display: none; }

    .hero { padding: 6.4rem 0 3rem; }
    .hero-grid {
      display: grid;
      grid-template-columns: 1.1fr .9fr;
      gap: 2rem;
      align-items: stretch;
    }
    .hero h1 {
      font-size: clamp(2.2rem, 5vw, 5rem);
      line-height: .95;
      letter-spacing: -0.04em;
      margin: 0 0 1.2rem;
      max-width: 15ch;
    }
    .hero p {
      color: #d4d4d4;
      max-width: 54ch;
      margin: 0 0 2rem;
      font-size: 1.05rem;
    }

    .hero-carousel {
      background: linear-gradient(165deg, #131313, #0d0d0d 60%);
      border: 1px solid #252525;
      border-radius: var(--radius);
      overflow: hidden;
      min-height: 360px;
      position: relative;
      box-shadow: var(--shadow);
    }

    .hero-slides { display: flex; transition: transform .55s cubic-bezier(.2,.8,.2,1); height: 100%; }
    .hero-slide { min-width: 100%; padding: 1.4rem; display: grid; grid-template-rows: 180px auto; gap: 1rem; }
    .hero-slide img { height: 180px; object-fit: cover; filter: saturate(.9) contrast(1.03); }
    .hero-slide h3 { margin: 0 0 .5rem; font-size: 1.3rem; }
    .hero-slide p { margin: 0; color: #c9c9c9; font-size: .95rem; }

    .carousel-controls {
      position: absolute;
      left: 1rem;
      right: 1rem;
      bottom: 1rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    .dots { display: flex; gap: .45rem; }
    .dot {
      width: 9px; height: 9px; border-radius: 999px;
      border: 0; background: #4a4a4a; cursor: pointer;
    }
    .dot.active { background: var(--accent); }

    .arrow-group { display: flex; gap: .4rem; }
    .icon-btn {
      width: 38px; height: 38px; border-radius: 999px; border: 1px solid #3a3a3a;
      background: rgba(18,18,18,.85); color: #fff; cursor: pointer;
    }

    .team-wrap {
      border: 1px solid #232323;
      border-radius: var(--radius);
      background: linear-gradient(180deg, #121212, #0f0f0f);
      padding: 1.2rem;
    }
    .region-tabs {
      display: flex;
      flex-wrap: wrap;
      gap: .6rem;
      margin-bottom: 1rem;
    }
    .region-tab {
      border: 1px solid #333;
      color: #dcdcdc;
      background: #131313;
      border-radius: 999px;
      padding: .5rem .95rem;
      cursor: pointer;
      min-height: 40px;
    }
    .region-tab.active {
      background: rgba(77,163,255,.16);
      border-color: rgba(77,163,255,.6);
      color: #f4f9ff;
    }

    .team-carousel {
      overflow: hidden;
      position: relative;
    }
    .team-track {
      display: flex;
      gap: 1rem;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      padding-bottom: .5rem;
      scroll-behavior: smooth;
    }
    .team-track::-webkit-scrollbar { height: 7px; }
    .team-track::-webkit-scrollbar-thumb { background: #2f2f2f; border-radius: 99px; }

    .team-card {
      flex: 0 0 clamp(260px, 40vw, 340px);
      background: var(--panel);
      border: 1px solid #262626;
      border-radius: 14px;
      padding: .9rem;
      scroll-snap-align: start;
      display: grid;
      gap: .8rem;
    }
    .team-card img { aspect-ratio: 4/3; object-fit: cover; }
    .team-meta h3 { margin: 0; font-size: 1.03rem; }
    .team-meta p { margin: .22rem 0 0; color: #bfbfbf; font-size: .9rem; }
    .quote { font-size: .95rem; color: #dfdfdf; }
    .office { color: var(--accent-2); font-size: .88rem; font-weight: 600; }

    .strip-head {
      display: flex;
      justify-content: space-between;
      align-items: end;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .h-scroll {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(260px, 360px);
      gap: 1rem;
      overflow-x: auto;
      padding-bottom: .45rem;
      scroll-snap-type: x mandatory;
      scroll-behavior: smooth;
    }

    .h-scroll::-webkit-scrollbar { height: 7px; }
    .h-scroll::-webkit-scrollbar-thumb { background: #2f2f2f; border-radius: 999px; }

    .project-card, .insight-card {
      scroll-snap-align: start;
      background: var(--panel);
      border: 1px solid #242424;
      border-radius: 14px;
      overflow: hidden;
      min-height: 100%;
    }
    .project-card img, .insight-card img { height: 180px; object-fit: cover; }
    .project-content, .insight-content { padding: .95rem; }
    .project-content h3, .insight-content h3 { margin: 0 0 .55rem; font-size: 1.05rem; }
    .project-content p, .insight-content p { margin: 0; color: #bcbcbc; font-size: .92rem; }

    .cta-banner {
      background: linear-gradient(135deg, #131b27, #19130d);
      border: 1px solid #2e2e2e;
      border-radius: 16px;
      padding: clamp(1.1rem, 3vw, 2rem);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .two-col {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 1rem;
    }

    .tile {
      background: var(--panel-2);
      border: 1px solid #282828;
      border-radius: 14px;
      padding: 1rem;
    }
    .tile h3 { margin: 0 0 .5rem; font-size: 1.02rem; }
    .tile p { margin: 0; color: #c8c8c8; font-size: .94rem; }

    .principles-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: .9rem;
    }

    .footer {
      border-top: 1px solid #262626;
      padding: 2.2rem 0 1.8rem;
      color: #b8b8b8;
    }
    .footer-top {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
      margin-bottom: 1rem;
    }

    .cookie-banner {
      position: fixed;
      left: 1rem;
      right: 1rem;
      bottom: 1rem;
      z-index: 60;
      background: #121212;
      border: 1px solid #2c2c2c;
      border-radius: 14px;
      padding: .95rem;
      box-shadow: var(--shadow);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .cookie-actions { display: flex; gap: .6rem; flex-wrap: wrap; }

    .reveal { opacity: 0; transform: translateY(12px); transition: opacity .45s ease, transform .45s ease; }
    .reveal.show { opacity: 1; transform: translateY(0); }

    @media (max-width: 980px) {
      .hero-grid { grid-template-columns: 1fr; }
      .nav-links {
        position: fixed;
        top: 76px;
        left: 0;
        right: 0;
        background: #0f0f0f;
        border-bottom: 1px solid #242424;
        padding: .9rem 1rem;
        transform: translateY(-120%);
        transition: transform .28s ease;
        flex-wrap: wrap;
      }
      .nav-links.open { transform: translateY(0); }
      .menu-toggle { display: inline-flex; }
      .two-col { grid-template-columns: 1fr; }
      .principles-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
    }

    @media (max-width: 620px) {
      .section { padding: 4.1rem 0; }
      .hero { padding-top: 5.1rem; }
      .principles-grid { grid-template-columns: 1fr; }
      .cookie-banner {
        flex-direction: column;
        align-items: flex-start;
      }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="container nav-wrap">
      <a class="brand" href="#hero">Leap<span>Studio</span></a>
      <nav class="nav-links" id="navLinks" aria-label="Primary navigation">
        <a href="#insights">Insights</a>
        <a href="#work">Work</a>
        <a href="#how">Services</a>
        <a href="#principles">Culture</a>
        <a href="#cta">Make Your Mark</a>
        <a href="#footer">Contact Us</a>
      </nav>
      <div class="nav-right">
        <div class="lang-toggle">
          <button class="btn btn-ghost" id="langToggle" aria-haspopup="true" aria-expanded="false">Global EN ▾</button>
          <div class="lang-menu" id="langMenu" role="menu" aria-label="Language selector">
            <button role="menuitem">Global EN</button>
            <button role="menuitem">France FR</button>
            <button role="menuitem">China CN</button>
          </div>
        </div>
        <button class="btn btn-ghost menu-toggle" id="menuToggle" aria-label="Toggle menu">☰</button>
      </div>
    </div>
  </header>

  <main>
    <section class="hero" id="hero">
      <div class="container hero-grid">
        <div class="reveal">
          <div class="eyebrow">Leap Studio — Global Creative Agency</div>
          <h1>Your Reinvention and Experience Partner</h1>
          <p>A global creative agency that challenges the status quo to create transformative experiences that win hearts and move markets in the eco-digital era.</p>
          <div style="display:flex; gap:.7rem; flex-wrap:wrap;">
            <a href="#work" class="btn btn-primary">Explore Client Work</a>
            <a href="#how" class="btn btn-ghost">How We Work</a>
          </div>
        </div>

        <div class="hero-carousel reveal" aria-label="Featured content carousel">
          <div class="hero-slides" id="heroSlides">
            <article class="hero-slide">
              <img src="https://images.unsplash.com/photo-1504384308090-c894fdcc538d?w=900&h=540&fit=crop&auto=format" alt="Report teaser visual" loading="lazy">
              <div>
                <h3>When Human Connection Meets AI</h3>
                <p>Report teaser — rethinking customer experience through empathy, intelligence, and adaptive service design.</p>
              </div>
            </article>
            <article class="hero-slide">
              <img src="https://images.unsplash.com/photo-1498050108023-c5249f4df085?w=900&h=540&fit=crop&auto=format" alt="Project highlight visual" loading="lazy">
              <div>
                <h3>Creating Consumer Insights at Scale</h3>
                <p>Project highlight — turning fragmented behavior signals into strategic growth actions across global markets.</p>
              </div>
            </article>
            <article class="hero-slide">
              <img src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=900&h=540&fit=crop&auto=format" alt="Podcast episode visual" loading="lazy">
              <div>
                <h3>Writing the Future of AI</h3>
                <p>Podcast episode — leaders discuss practical AI governance, experimentation, and sustainable impact at enterprise scale.</p>
              </div>
            </article>
          </div>
          <div class="carousel-controls">
            <div class="dots" id="heroDots"></div>
            <div class="arrow-group">
              <button class="icon-btn" id="heroPrev" aria-label="Previous hero slide">←</button>
              <button class="icon-btn" id="heroNext" aria-label="Next hero slide">→</button>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="team">
      <div class="container">
        <div class="eyebrow">Global Studios</div>
        <h2>People shaping reinvention worldwide</h2>
        <div class="team-wrap reveal">
          <div class="region-tabs" id="regionTabs" role="tablist" aria-label="Team regions">
            <button class="region-tab active" data-region="North America" role="tab" aria-selected="true">North America</button>
            <button class="region-tab" data-region="Asia" role="tab" aria-selected="false">Asia</button>
            <button class="region-tab" data-region="Europe" role="tab" aria-selected="false">Europe</button>
            <button class="region-tab" data-region="Oceania" role="tab" aria-selected="false">Oceania</button>
          </div>
          <div class="team-carousel" aria-live="polite">
            <div class="team-track" id="teamTrack"></div>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="work">
      <div class="container">
        <div class="strip-head">
          <div>
            <div class="eyebrow">Client Work</div>
            <h2>Transformation stories that move markets</h2>
          </div>
          <div class="arrow-group">
            <button class="icon-btn" id="workPrev" aria-label="Scroll work left">←</button>
            <button class="icon-btn" id="workNext" aria-label="Scroll work right">→</button>
          </div>
        </div>

        <div class="h-scroll reveal" id="workTrack" aria-label="Work showcase carousel">
          <article class="project-card">
            <img src="https://images.unsplash.com/photo-1552664730-d307ca884978?w=900&h=600&fit=crop&auto=format" alt="Creating Consumer Insights at Scale" loading="lazy">
            <div class="project-content"><h3>Creating Consumer Insights at Scale</h3><p>Enterprise analytics platform connecting signal to strategy.</p></div>
          </article>
          <article class="project-card">
            <img src="https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=900&h=600&fit=crop&auto=format" alt="Deepening Customer Engagement" loading="lazy">
            <div class="project-content"><h3>Deepening Customer Engagement</h3><p>Omnichannel journey redesign with measurable loyalty lift.</p></div>
          </article>
          <article class="project-card">
            <img src="https://images.unsplash.com/photo-1485827404703-89b55fcc595e?w=900&h=600&fit=crop&auto=format" alt="Harnessing Data for Leaner and Greener Future of Mobility" loading="lazy">
            <div class="project-content"><h3>Harnessing Data for Leaner and Greener Future of Mobility</h3><p>Intelligent operations reducing waste while improving throughput.</p></div>
          </article>
          <article class="project-card">
            <img src="https://images.unsplash.com/photo-1520607162513-77705c0f0d4a?w=900&h=600&fit=crop&auto=format" alt="Modernizing the Point-of-Sale Experience" loading="lazy">
            <div class="project-content"><h3>Modernizing the Point-of-Sale Experience</h3><p>Retail POS reinvention built for speed, trust, and conversion.</p></div>
          </article>
          <article class="project-card">
            <img src="https://images.unsplash.com/photo-1524504388940-b1c1722653e1?w=900&h=600&fit=crop&auto=format" alt="Reimagining Luxury Craftsmanship" loading="lazy">
            <div class="project-content"><h3>Reimagining Luxury Craftsmanship</h3><p>Digital storytelling that scales heritage to a global audience.</p></div>
          </article>
          <article class="project-card">
            <img src="https://images.unsplash.com/photo-1576091160550-2173dba999ef?w=900&h=600&fit=crop&auto=format" alt="Helping Healthier Habits Stick" loading="lazy">
            <div class="project-content"><h3>Helping Healthier Habits Stick</h3><p>Behavior-centered service design to sustain healthier routines.</p></div>
          </article>
        </div>
      </div>
    </section>

    <section class="section" id="cta">
      <div class="container">
        <div class="cta-banner reveal">
          <div>
            <div class="eyebrow" style="color:var(--accent-2)">Ready to transform?</div>
            <h2 style="margin:0; font-size:clamp(1.4rem,2.7vw,2.2rem)">Let’s create what markets remember.</h2>
          </div>
          <a href="#footer" class="btn btn-primary">Start a Conversation</a>
        </div>
      </div>
    </section>

    <section class="section" id="how">
      <div class="container">
        <div class="eyebrow">How We Work</div>
        <h2>Artful strategy. Systems-level execution.</h2>
        <div class="two-col reveal">
          <article class="tile"><h3>Discover</h3><p>We align stakeholder ambition with ecosystem reality through immersive diagnostics and strategic framing.</p></article>
          <article class="tile"><h3>Design</h3><p>We fuse art and science to design product, service, and brand experiences built for relevance and resilience.</p></article>
          <article class="tile"><h3>Scale</h3><p>We operationalize innovation through platforms, governance, and capabilities that endure across regions.</p></article>
          <article class="tile"><h3>Regenerate</h3><p>We prioritize long-term impact, renewing systems and communities while accelerating business outcomes.</p></article>
        </div>
      </div>
    </section>

    <section class="section" id="insights">
      <div class="container">
        <div class="eyebrow">Latest Insights</div>
        <h2>Signals, stories, and strategic perspectives</h2>
        <div class="h-scroll reveal">
          <article class="insight-card"><img src="https://images.unsplash.com/photo-1507146153580-69a1fe6d8aa1?w=900&h=540&fit=crop&auto=format" alt="When Human Connection Meets AI" loading="lazy"><div class="insight-content"><h3>When Human Connection Meets AI</h3><p>Report</p></div></article>
          <article class="insight-card"><img src="https://images.unsplash.com/photo-1456324504439-367cee3b3c32?w=900&h=540&fit=crop&auto=format" alt="Writing the Future of AI" loading="lazy"><div class="insight-content"><h3>Writing the Future of AI</h3><p>Podcast</p></div></article>
          <article class="insight-card"><img src="https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=900&h=540&fit=crop&auto=format" alt="Amplifying Clinical Care with AI" loading="lazy"><div class="insight-content"><h3>Amplifying Clinical Care with AI</h3><p>Article</p></div></article>
          <article class="insight-card"><img src="https://images.unsplash.com/photo-1553877522-43269d4ea984?w=900&h=540&fit=crop&auto=format" alt="The Future of Customer Experience" loading="lazy"><div class="insight-content"><h3>The Future of Customer Experience</h3><p>Insight</p></div></article>
          <article class="insight-card"><img src="https://images.unsplash.com/photo-1531482615713-2afd69097998?w=900&h=540&fit=crop&auto=format" alt="Next-Gen Contact Centers: Powered by AI" loading="lazy"><div class="insight-content"><h3>Next-Gen Contact Centers: Powered by AI</h3><p>Report</p></div></article>
          <article class="insight-card"><img src="https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?w=900&h=540&fit=crop&auto=format" alt="From Complexity to Clarity" loading="lazy"><div class="insight-content"><h3>From Complexity to Clarity</h3><p>Perspective</p></div></article>
        </div>
      </div>
    </section>

    <section class="section" id="principles">
      <div class="container">
        <div class="eyebrow">Our Principles</div>
        <h2>What defines Leap Studio</h2>
        <div class="principles-grid reveal">
          <article class="tile"><h3>Challenge the status quo</h3><p>We ask sharper questions and expand strategic possibility beyond familiar patterns.</p></article>
