  <script>
    const heroSlides = document.getElementById('heroSlides');
    const heroPrev = document.getElementById('heroPrev');
    const heroNext = document.getElementById('heroNext');
    const heroDots = document.getElementById('heroDots');
    const slideCount = heroSlides.children.length;
    let heroIndex = 0;
    let heroTimer;

    function renderHeroDots() {
      heroDots.innerHTML = '';
      for (let i = 0; i < slideCount; i++) {
        const dot = document.createElement('button');
        dot.className = 'dot' + (i === heroIndex ? ' active' : '');
        dot.setAttribute('aria-label', `Go to slide ${i + 1}`);
        dot.addEventListener('click', () => { heroIndex = i; updateHero(); resetHeroAuto(); });
        heroDots.appendChild(dot);
      }
    }

    function updateHero() {
      heroSlides.style.transform = `translateX(-${heroIndex * 100}%)`;
      [...heroDots.children].forEach((d, i) => d.classList.toggle('active', i === heroIndex));
    }

    function nextHero(step = 1) {
      heroIndex = (heroIndex + step + slideCount) % slideCount;
      updateHero();
    }

    function resetHeroAuto() {
      clearInterval(heroTimer);
      heroTimer = setInterval(() => nextHero(1), 5000);
    }

    heroPrev.addEventListener('click', () => { nextHero(-1); resetHeroAuto(); });
    heroNext.addEventListener('click', () => { nextHero(1); resetHeroAuto(); });

    renderHeroDots();
    updateHero();
    resetHeroAuto();

    const teamData = {
      'North America': [
        { name: 'Avery Morgan', title: 'Executive Creative Director', quote: 'The best transformations feel inevitable in hindsight.', office: 'New York', image: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=700&h=500&fit=crop&auto=format' },
        { name: 'Jordan Lee', title: 'VP, Experience Strategy', quote: 'We design systems people trust, not just interfaces they use.', office: 'San Francisco', image: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=700&h=500&fit=crop&auto=format' }
      ],
      'Asia': [
        { name: 'Mei Tan', title: 'Head of Service Design', quote: 'Cultural nuance is a strategic advantage, not a constraint.', office: 'Singapore', image: 'https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?w=700&h=500&fit=crop&auto=format' },
        { name: 'Arjun Patel', title: 'Design Technology Lead', quote: 'Great products are choreography between human intent and machine speed.', office: 'Singapore', image: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=700&h=500&fit=crop&auto=format' }
      ],
      'Europe': [
        { name: 'Sofia Klein', title: 'Principal Brand Strategist', quote: 'A brand is a behavior system, not a visual asset.', office: 'Munich', image: 'https://images.unsplash.com/photo-1542204625-de293a2b3d8f?w=700&h=500&fit=crop&auto=format' },
        { name: 'Elias Ward', title: 'Client Partner, Innovation', quote: 'Ambition becomes momentum when governance is designed in.', office: 'London', image: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=700&h=500&fit=crop&auto=format' }
      ],
      'Oceania': [
        { name: 'Harper Nguyen', title: 'Director, Experience Programs', quote: 'We make complex service ecosystems feel radically simple.', office: 'Melbourne', image: 'https://images.unsplash.com/photo-1531123897727-8f129e1688ce?w=700&h=500&fit=crop&auto=format' },
        { name: 'Riley Scott', title: 'Transformation Consultant', quote: 'Reinvention scales when teams own the change story.', office: 'Melbourne', image: 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=700&h=500&fit=crop&auto=format' }
      ]
    };

    const regionTabs = document.querySelectorAll('.region-tab');
    const teamTrack = document.getElementById('teamTrack');

    function renderTeam(region) {
      const members = teamData[region] || [];
      teamTrack.innerHTML = members.map(member => `
        <article class="team-card">
          <img src="${member.image}" alt="${member.name} portrait" loading="lazy">
          <div class="team-meta">
            <h3>${member.name}</h3>
            <p>${member.title}</p>
          </div>
          <p class="quote">“${member.quote}”</p>
          <a href="#footer" class="office">${member.office} Office ↗</a>
        </article>
      `).join('');
      teamTrack.scrollLeft = 0;
    }

    regionTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        regionTabs.forEach(t => {
          t.classList.remove('active');
          t.setAttribute('aria-selected', 'false');
        });
        tab.classList.add('active');
        tab.setAttribute('aria-selected', 'true');
        renderTeam(tab.dataset.region);
      });
    });

    renderTeam('North America');

    const workTrack = document.getElementById('workTrack');
    document.getElementById('workPrev').addEventListener('click', () => {
      workTrack.scrollBy({ left: -340, behavior: 'smooth' });
    });
    document.getElementById('workNext').addEventListener('click', () => {
      workTrack.scrollBy({ left: 340, behavior: 'smooth' });
    });

    const langToggle = document.getElementById('langToggle');
    const langMenu = document.getElementById('langMenu');

    langToggle.addEventListener('click', () => {
      const show = langMenu.classList.toggle('show');
      langToggle.setAttribute('aria-expanded', String(show));
    });

    document.addEventListener('click', (e) => {
      if (!e.target.closest('.lang-toggle')) {
        langMenu.classList.remove('show');
        langToggle.setAttribute('aria-expanded', 'false');
      }
    });

    langMenu.querySelectorAll('button').forEach(btn => {
      btn.addEventListener('click', () => {
        langToggle.textContent = btn.textContent + ' ▾';
        langMenu.classList.remove('show');
        langToggle.setAttribute('aria-expanded', 'false');
      });
    });

    const menuToggle = document.getElementById('menuToggle');
    const navLinks = document.getElementById('navLinks');
    menuToggle.addEventListener('click', () => navLinks.classList.toggle('open'));
    navLinks.querySelectorAll('a').forEach(link => link.addEventListener('click', () => navLinks.classList.remove('open')));

    const cookieBanner = document.getElementById('cookieBanner');
    const cookieButtons = ['cookieAccept', 'cookieManage', 'cookieDecline'].map(id => document.getElementById(id));
    cookieButtons.forEach(btn => btn.addEventListener('click', () => cookieBanner.style.display = 'none'));

    const io = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) entry.target.classList.add('show');
      });
    }, { threshold: .12 });

    document.querySelectorAll('.reveal').forEach(el => io.observe(el));
  </script>
